#!/bin/sh
# Generated by YDK go-http-service from ydk:test:system/round-trip.e2e.
# Cases a-to-b..lru-eviction are implemented; e2e-latency, kafka-down, restart-resume are stubs (task #37).
set -eu
. "$(dirname "$0")/lib.sh"

RUN="$$-$(date +%s)"

# send <host> <user> <text>: POST a message; fails unless 202.
send() {
  [ "$(http_status "$1" POST /api/messages "{\"user\":\"$2\",\"text\":\"$3\"}")" = 202 ] || fail "POST $2 on $1 not 202"
}

# messages <host> <user>: prints the JSON array for the user.
messages() {
  http_get "$1" "/api/messages?user=$2"
}

# wait_text <host> <user> <fixed-string...>: poll every 250 ms up to 10 s until the body contains any of the strings.
wait_text() {
  wt_host=$1
  wt_user=$2
  shift 2
  wt_i=0
  while [ "$wt_i" -lt 40 ]; do
    wt_body=$(messages "$wt_host" "$wt_user") || wt_body=
    for wt_s in "$@"; do
      case "$wt_body" in *"$wt_s"*) return 0 ;; esac
    done
    wt_i=$((wt_i + 1))
    sleep 0.25
  done
  fail "'$1' not seen for $wt_user on $wt_host within 10 s (last body: $wt_body)"
}

# post_check <host> <json> <status> <error message>: POST and assert status and exact error body.
post_check() {
  pc_out=$(curl -sS -w '\n%{http_code}' -H "Host: $1" -H 'Content-Type: application/json' -d "$2" "$BASE_URL/api/messages")
  pc_code=$(printf '%s' "$pc_out" | tail -n 1)
  pc_body=$(printf '%s' "$pc_out" | sed '$d')
  [ "$pc_code" = "$3" ] || fail "expected status $3, got $pc_code ($pc_body)"
  [ "$pc_body" = "{\"error\":\"$4\"}" ] || fail "expected error '$4', got $pc_body"
}

# warm_up <from-host> <to-host> <tag>: resend a probe every 1 s (up to 30 s) until it arrives, proving the
# receiving consumer group has joined (it starts at latest, ADR-017).
warm_up() {
  wu_i=0
  while [ "$wu_i" -lt 30 ]; do
    send "$1" "warm-$3-$RUN" "probe$3"
    sleep 1
    case "$(messages "$2" "warm-$3-$RUN" || true)" in *"probe$3"*) return 0 ;; esac
    wu_i=$((wu_i + 1))
  done
  fail "warm-up $3 did not arrive within 30 s"
}

wait_ready "$HOST_CLOPY_PASTE_A"
wait_ready "$HOST_CLOPY_PASTE_B"
warm_up "$HOST_CLOPY_PASTE_A" "$HOST_CLOPY_PASTE_B" ab
warm_up "$HOST_CLOPY_PASTE_B" "$HOST_CLOPY_PASTE_A" ba

# ydk:test:system/round-trip.e2e case=a-to-b
# Send on A appears on B
# given: Both releases Ready; warm-up done: probe messages A->B and B->A resent every 1 s (up to 30 s) until each arrives, proving both new consumer groups joined (they start at latest, ADR-017)
# when: POST on A as bob with a unique text; poll GET bob on B every 250 ms up to 10 s
# then: B returns the text; GET bob on A returns [] (ydk:req:messaging/sent-not-stored)
case_a_to_b() {
  u="bob-$RUN"
  t="hello$RUN"
  send "$HOST_CLOPY_PASTE_A" "$u" "$t"
  wait_text "$HOST_CLOPY_PASTE_B" "$u" "$t"
  [ "$(messages "$HOST_CLOPY_PASTE_A" "$u")" = "[]" ] || fail "sent message was stored on A"
}

# ydk:test:system/round-trip.e2e case=b-to-a
# Reply direction (B uses PLAINTEXT, A uses SASL_SSL)
# given: Both releases Ready
# when: POST on B as bob; poll A
# then: A returns the text
case_b_to_a() {
  u="bob-ba-$RUN"
  t="reply$RUN"
  send "$HOST_CLOPY_PASTE_B" "$u" "$t"
  wait_text "$HOST_CLOPY_PASTE_A" "$u" "$t"
}

# ydk:test:system/round-trip.e2e case=censoring
# ydk:req:messaging/censor-denylist end to end
# given: Default CENSOR_CHARS
# when: POST on A user 'eve$' text 'a$b!c~'
# then: GET 'eve_' on B returns 'a_b_c_'; GET 'eve$' on B returns the same
case_censoring() {
  send "$HOST_CLOPY_PASTE_A" "eve$RUN"'$' 'a$b!c~'"$RUN"
  wait_text "$HOST_CLOPY_PASTE_B" "eve${RUN}_" "a_b_c_$RUN"
  case "$(messages "$HOST_CLOPY_PASTE_B" "eve$RUN%24")" in *"a_b_c_$RUN"*) ;; *) fail "censored lookup with raw user missed" ;; esac
}

# ydk:test:system/round-trip.e2e case=limits
# ydk:req:messaging/text-length and ydk:req:messaging/user-length
# given: A Ready
# when: POST 1001-code-point text; POST 129-code-point user
# then: 400 with exact messages; nothing appears on B
case_limits() {
  u="lim-$RUN"
  long_text=$(awk 'BEGIN { for (i = 0; i < 1001; i++) printf "a" }')
  long_user=$(awk 'BEGIN { for (i = 0; i < 129; i++) printf "u" }')
  post_check "$HOST_CLOPY_PASTE_A" "{\"user\":\"$u\",\"text\":\"$long_text\"}" 400 'text must be 1..1000 characters'
  post_check "$HOST_CLOPY_PASTE_A" "{\"user\":\"$long_user\",\"text\":\"x\"}" 400 'user must be 1..128 characters'
  sleep 3
  [ "$(messages "$HOST_CLOPY_PASTE_B" "$u")" = "[]" ] || fail "rejected message reached B"
}

# ydk:test:system/round-trip.e2e case=plain-text
# ydk:req:ui/plain-text-rendering at API level
# given: A Ready
# when: POST text '<img src=x onerror=alert(1)>'
# then: B returns it byte-identical; lint stage greps index.html and fails on any innerHTML or insertAdjacentHTML use
case_plain_text() {
  u="xss-$RUN"
  send "$HOST_CLOPY_PASTE_A" "$u" '<img src=x onerror=alert(1)>'
  # The JSON encoder escapes < and > as \u003c and \u003e; accept both forms.
  wait_text "$HOST_CLOPY_PASTE_B" "$u" '<img src=x onerror=alert(1)>' '\u003cimg src=x onerror=alert(1)\u003e'
}

# ydk:test:system/round-trip.e2e case=lru-eviction
# ydk:req:messaging/lru-eviction
# given: B store fresh (pod restarted)
# when: POST on A for u001..u101 one message each; wait for u101 on B
# then: GET u001 on B returns []; GET u002 returns 1 item
case_lru_eviction() {
  # B is not restarted (HTTP only): earlier users are older than u001, so u001 is still the first of
  # the u001..u101 batch to be evicted and u002 survives. Wait for the first two in order, then the rest.
  send "$HOST_CLOPY_PASTE_A" u001 m001
  wait_text "$HOST_CLOPY_PASTE_B" u001 m001
  send "$HOST_CLOPY_PASTE_A" u002 m002
  wait_text "$HOST_CLOPY_PASTE_B" u002 m002
  n=3
  while [ "$n" -le 101 ]; do
    id=$(printf 'u%03d' "$n")
    send "$HOST_CLOPY_PASTE_A" "$id" "m$id"
    # Topics have 3 partitions: wait for each message so arrival order is the send order.
    wait_text "$HOST_CLOPY_PASTE_B" "$id" "m$id"
    n=$((n + 1))
  done
  [ "$(messages "$HOST_CLOPY_PASTE_B" u001)" = "[]" ] || fail "u001 not evicted"
  case "$(messages "$HOST_CLOPY_PASTE_B" u002)" in *m002*) ;; *) fail "u002 was evicted" ;; esac
}

