# ydk:error:api/kafka-unavailable; readiness independent of Kafka (ADR-016)
# given: Kafka broker pod scaled to 0 (Strimzi KafkaNodePool replicas 0)
# when: POST on A through its Ingress; GET page and readiness on A
# then: POST 503 with JSON body {error:'kafka unavailable, message not sent'}; page 200; readiness 200; pod stays Ready, restartCount unchanged; after broker returns, POST 202
case_kafka_down() {
  echo 'not implemented: kafka-down'
  return 1
}

# ydk:test:system/round-trip.e2e case=restart-resume
# ydk:nfr:system/availability and ydk:nfr:system/startup-time
# given: B pod deleted
# when: POST on A while B is down; wait for B Ready
# then: B Ready <= 10 s after container start; message displayed on B
case_restart_resume() {
  echo 'not implemented: restart-resume'
  return 1
}

failed=0
for c in case_a_to_b case_b_to_a case_censoring case_limits case_plain_text case_lru_eviction case_e2e_latency case_kafka_down case_restart_resume; do
  # set -e must stay active inside each case, so the subshell is not an if/&&/|| operand.
  set +e
  ( set -e; "$c" )
  rc=$?
  set -e
  if [ "$rc" -eq 0 ]; then
    echo "ok: $c"
  else
    echo "FAIL: $c"
    failed=1
  fi
done
exit "$failed"
